#!/usr/bin/env python3
import os
from generators.Generator import Generator
import Command


class RmgGenerator(Generator):
    def generate(self, system, rom, playersControllers, metadata, guns, wheels, gameResolution):
        # Enforce Piccolo [AX] 2:3:1 core affinity & HugeTLB environment
        env = os.environ.copy()
        env["AX_PROFILE"] = "piccolo_n64"
        env["AX_AUDIO_LATENCY_MS"] = "2"

        # Launch RMG headless (no Qt desktop chrome) straight into the ROM
        commandArray = [
            "/usr/bin/RMG",
            "--nogui",
            "--fullscreen",
            rom,
        ]

        return Command.Command(array=commandArray, env=env)
